import json,re,time,statistics,collections
from transformers import AutoTokenizer
ann='reproduction/GRACE/ShareGPT4V/sharegpt4v_mix665k_cap23k_coco-ap9k_lcs3k_sam9k_div2k.json'
model='reproduction/GRACE/models/Qwen3-VL-2B-Instruct'
tok=AutoTokenizer.from_pretrained(model,local_files_only=True)
with open(ann) as f:data=json.load(f)
pat=re.compile(r'(<image>|<video>)')
def render(x):
 out=[]
 for turn in x['conversations']:
  role='user' if turn['from']=='human' else 'assistant'
  out.extend(('<|im_start|>',role,'\n'))
  val=str(turn.get('value',''))
  if role=='user':
   for seg in pat.split(val):
    if seg=='<image>':out.append('<|vision_start|><|image_pad|><|vision_end|>\n')
    elif seg=='<video>':out.append('<|vision_start|><|video_pad|><|vision_end|>\n')
    elif seg.strip():out.append(seg.strip())
  else: out.append(val)
  out.append('<|im_end|>\n')
 return ''.join(out)
lengths=[]; rows=[]; st=time.time(); bs=4000
backend=tok.backend_tokenizer
for start in range(0,len(data),bs):
 texts=[render(x) for x in data[start:start+bs]]
 encs=backend.encode_batch(texts,add_special_tokens=False)
 for off,e in enumerate(encs):
  x=data[start+off]; n=len(e.ids)
  # Processor replaces one image-pad token with N merged image-pad tokens.
  # Exact N is 2..196, median 187. Record base and conservative upper bound.
  has_img=bool(x.get('image')); upper=n+(195 if has_img else 0)
  lengths.append(n); rows.append((upper,n,len(x['conversations']),start+off,x.get('id'),x.get('image')))
 if start and start%80000==0:print('tokenized',start,'sec',round(time.time()-st,1),flush=True)
def pct(a,p):return sorted(a)[round((len(a)-1)*p)]
print('elapsed',round(time.time()-st,1),'count',len(lengths))
for p in [.5,.9,.95,.99,.999,.9999]:print('base_p',p,pct(lengths,p))
print('base_mean',round(statistics.mean(lengths),2),'base_max',max(lengths))
for threshold in [1024,2048,3072,4096,6144,8192]:
 print('conservative_upper_ge',threshold,sum(r[0]>=threshold for r in rows),'base_ge',sum(r[1]>=threshold for r in rows))
print('top')
for r in sorted(rows,reverse=True)[:80]:print(r)
