from wandb.sdk.internal.datastore import DataStore
from wandb.proto import wandb_internal_pb2
for p in sorted(glob.glob('reproduction/GRACE/models/Qwen3-VL-2B-SFT-BF16/wandb/wandb/offline-run-*/run-*.wandb')):
 ds=DataStore();ds.open_for_scan(p);cfg={};mx={};hist=[];out=[];summ={};exitcode=None
 while True:
  b=ds.scan_data()
  if b is None:break
  r=wandb_internal_pb2.Record();r.ParseFromString(b);typ=r.WhichOneof('record_type')
  if typ=='config':
   for x in r.config.update:
    try:cfg[x.key]=json.loads(x.value_json)
    except:cfg[x.key]=x.value_json
  elif typ=='stats':
   for x in r.stats.item:
    if re.fullmatch(r'gpu\.\d+\.(memory|memoryAllocated|memoryAllocatedBytes|gpu)',x.key):
     try:v=float(json.loads(x.value_json));mx[x.key]=max(mx.get(x.key,float('-inf')),v)
     except:pass
  elif typ=='history':
   h={}
   for x in r.history.item:
    k='/'.join(x.nested_key) if x.nested_key else x.key
    try:h[k]=json.loads(x.value_json)
    except:h[k]=x.value_json
   hist.append(h)
  elif typ=='summary':
   for x in r.summary.update:
    k='/'.join(x.nested_key) if x.nested_key else x.key
    try:summ[k]=json.loads(x.value_json)
    except:summ[k]=x.value_json
  elif typ=='output_raw':
   out.append(r.output_raw.line)
  elif typ=='exit':exitcode=r.exit.exit_code
 print('\nRUN',os.path.basename(os.path.dirname(p)), 'fileMB',round(os.path.getsize(p)/1e6,2))
 print('config batch',cfg.get('per_device_train_batch_size'),'accum',cfg.get('gradient_accumulation_steps'),'maxlen',cfg.get('model_max_length'),'liger',cfg.get('use_liger_kernel'),'deepspeed',cfg.get('deepspeed'),'resume',cfg.get('_name_or_path'))
 print('history rows',len(hist),'max global step',max([h.get('train/global_step',-1) for h in hist],default=-1),'runtime',summ.get('_runtime'),'exit',exitcode)
 print('gpu maxima',dict(sorted(mx.items())))
 interesting=[s.rstrip() for s in out if re.search(r'out of memory|OOM|CUDA|Traceback|Error|failed|exception|Killed|step|reserved|allocated',s,re.I)]
 print('interesting tail')
 print('\n'.join(interesting[-80:]))
 print('raw tail')
 print('\n'.join(s.rstrip() for s in out[-20:]))
