import json
import struct
import urllib.request
from concurrent.futures import ThreadPoolExecutor
checks = [
 ('MMBench legacy', 'https://opencompass.openxlab.space/utils/MMBench/MMBench_DEV_EN_legacy.tsv', False),
 ('MMStar', 'https://opencompass.openxlab.space/utils/VLMEval/MMStar.tsv', False),
 ('ScienceQA test archive', 'https://scienceqa.s3.us-west-1.amazonaws.com/images/test.zip', True),
 ('SEED image archive', 'https://huggingface.co/datasets/AILab-CVC/SEED-Bench/resolve/main/SEED-Bench-image.zip', True),
]
def inspect(item):
    label, url, archive = item
    try:
        req = urllib.request.Request(url, method='GET' if archive else 'HEAD', headers={'Range': 'bytes=0-4095'} if archive else {})
        with urllib.request.urlopen(req, timeout=25) as response:
            result = {'name': label, 'status': response.status, 'content_type': response.headers.get('Content-Type'), 'size_or_range': response.headers.get('Content-Range') or response.headers.get('Content-Length')}
            if archive:
                block = response.read(4096)
                if block[:4] == b'PK\x03\x04':
                    name_len = struct.unpack_from('<H', block, 26)[0]
                    result['first_archive_entry'] = block[30:30+name_len].decode('utf-8')
                else:
                    result['zip_header'] = repr(block[:20])
            return result
    except Exception as exc:
        return {'name': label, 'error': str(exc)}
with ThreadPoolExecutor(max_workers=4) as pool:
    for result in pool.map(inspect, checks):
        print(json.dumps(result))
